deco.css:
.fd-orb{position:fixed;top:1vh;left:1vw;width:96px;height:96px;border-radius:50%;border:1.5px solid rgba(46,123,166,.30);background:radial-gradient(circle at 36% 32%,rgba(111,168,79,.20),rgba(46,123,166,.07) 58%,rgba(0,0,0,0) 72%);opacity:.85;animation:fd-float 26s ease-in-out infinite;pointer-events:none}
.fd-sea{position:fixed;left:0;bottom:0;width:100%;height:6vh;border-radius:50% 50% 0 0/70% 70% 0 0;background:linear-gradient(180deg,rgba(46,123,166,.16),rgba(46,123,166,.03));pointer-events:none}
.fd-leaf{position:fixed;top:6vh;right:2vw;width:44px;height:44px;border-radius:0 100% 0 100%;background:linear-gradient(135deg,#9ACB72,#4E8A3C);opacity:.4;transform:rotate(-14deg);pointer-events:none}
.fd-glow{position:fixed;top:0;right:0;width:8vw;height:10vh;background:radial-gradient(ellipse at 100% 0,rgba(255,255,255,.6),rgba(255,255,255,0) 70%);pointer-events:none}
@keyframes fd-float{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}
@media (prefers-reduced-motion: reduce){.fd-orb{animation:none}}
